import fs from 'fs-extra'
import path from 'path'

export const AGENTS_START_MARKER = '<!-- portman:start -->'
export const AGENTS_END_MARKER = '<!-- portman:end -->'

// Locations of the Portman CLI options file, as generated by `portman --init`
const CLI_OPTIONS_FILES = ['portman-cli.json', 'portman/portman-cli.json']

export const renderAgentInstructions = (cliOptionsFile?: string): string => {
  const runCommand = cliOptionsFile
    ? `npx @apideck/portman --cliOptionsFile ${cliOptionsFile}`
    : 'npx @apideck/portman -l <openapi-file> -c portman-config.json -b <baseUrl> --runNewman'

  return [
    AGENTS_START_MARKER,
    '## API contract tests (Portman)',
    '',
    'This repository uses [Portman](https://getportman.com) to generate contract tests from the OpenAPI',
    'document and run them against the API with Newman.',
    '',
    '### Run the contract tests',
    '',
    '```sh',
    runCommand,
    '```',
    '',
    'Portman runs Newman with `abortOnFailure` enabled, so the run stops at the first failure. To see all',
    'failures, append:',
    '',
    '```sh',
    `--newmanRunOptions '{"abortOnFailure":false}'`,
    '```',
    '',
    '### When a contract test fails',
    '',
    '- A failing contract test means the implementation and the OpenAPI spec disagree. Fix the code, or',
    '  deliberately change the OpenAPI spec when the contract itself has to change, and call that out.',
    '- Never edit the generated Postman collection to get a green run. It is regenerated on every run.',
    '- Never disable checks, add `excludeForOperations`, or otherwise weaken `portman-config.json` to make',
    '  failing tests pass.',
    '',
    '### Docs',
    '',
    '- Documentation: https://getportman.com/docs',
    '- Docs MCP server: https://getportman.com/mcp',
    AGENTS_END_MARKER
  ].join('\n')
}

export const upsertAgentInstructions = (content: string, instructions: string): string => {
  const start = content.indexOf(AGENTS_START_MARKER)
  const end = content.indexOf(AGENTS_END_MARKER, start)

  // Replace the existing Portman block
  if (start !== -1 && end !== -1) {
    return content.slice(0, start) + instructions + content.slice(end + AGENTS_END_MARKER.length)
  }

  // Append the Portman block
  if (content.trim() === '') return `${instructions}\n`
  return `${content.replace(/\n*$/, '')}\n\n${instructions}\n`
}

/**
 * Writes the Portman instructions for coding agents to AGENTS.md, and to CLAUDE.md when it exists.
 * Returns the paths of the written files.
 */
export const initAgents = (cwd: string = process.cwd()): string[] => {
  const cliOptionsFile = CLI_OPTIONS_FILES.find(file => fs.existsSync(path.join(cwd, file)))
  const instructions = renderAgentInstructions(cliOptionsFile)

  const targetFiles = [path.join(cwd, 'AGENTS.md')]
  const claudeFile = path.join(cwd, 'CLAUDE.md')
  if (fs.existsSync(claudeFile)) targetFiles.push(claudeFile)

  return targetFiles.map(file => {
    const content = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : ''
    fs.writeFileSync(file, upsertAgentInstructions(content, instructions), 'utf8')
    return file
  })
}
